mapper.select:
SELECT r.id, r.order_id, r.product_id, p.title AS product_title, (SELECT pi.image_url FROM product_image pi WHERE pi.product_id = r.product_id ORDER BY pi.is_cover DESC, pi.sort ASC LIMIT 1) AS product_image, r.buyer_id, bu.account AS buyer_name, bu.avatar AS buyer_avatar, r.seller_id, su.account AS seller_name, r.rating, r.content, r.reply_content, r.reply_time, r.status, r.create_time, r.update_time FROM product_review r LEFT JOIN product p ON r.product_id = p.id LEFT JOIN base_user bu ON r.buyer_id = bu.id LEFT JOIN base_user su ON r.seller_id = su.id
AND r.product_id = #{productId}
AND r.seller_id = #{sellerId}
AND r.buyer_id = #{buyerId}
AND r.rating = #{rating}
AND r.status = #{status}
AND r.reply_content IS NOT NULL AND r.reply_content != ''
AND (r.reply_content IS NULL OR r.reply_content = '')
AND r.content LIKE CONCAT('%', #{keyword}, '%')
ORDER BY r.create_time DESC
LIMIT #{current}, #{size}

SELECT COUNT(*)
FROM product_review r


        AND r.product_id = #{productId}


        AND r.seller_id = #{sellerId}


        AND r.buyer_id = #{buyerId}


        AND r.rating = #{rating}


        AND r.status = #{status}


        AND r.reply_content IS NOT NULL AND r.reply_content != ''


        AND (r.reply_content IS NULL OR r.reply_content = '')


        AND r.content LIKE CONCAT('%', #{keyword}, '%')
